from research_helpers import *
a=ev('https://kairospharma.com/technologies/','Issuer names seven programmes:ENV105,KROS101/102/201/301/401,ENV205 and explains mechanisms. Candidate drugs are investigational,not approved products.')
b=ev('https://kairospharma.com/pipeline/','Issuer public pipeline and historical milestones checked. Future horizon/IND clearance not evidence approval or actual trial initiation.')
c=ev('https://www.sec.gov/Archives/edgar/data/1962011/000149315226034185/ex99-1.htm','July22 2026 issuer identifies ENV105 as carotuximab in planned collaboration with Bayer. Bayer XOFIGO is combination partner drug,not a Kairos-owned product.')
d=ev('https://investors.kairospharma.com/overview/default.aspx','Current issuer overview identifies ENV105 in Phase2 prostate and Phase1 lung trials.')
e=ev('https://www.sec.gov/Archives/edgar/data/1962011/000149315226025021/formars.pdf','2026 annual filing identifies all seven programmes and KROS401 as cyclic peptide rather than generic small-molecule label in older diagram. KROS101 text and diagrams differ agonist/antagonist wording; no unsupported definitive direction normalized.')
specs=[('ENV-105','Carotuximab investigational CD105/endoglin-directed antibody studied in prostate and lung cancer.','development',['ENV105','Carotuximab']),('KROS-101','Investigational GITR-pathway immune modulator; actual clinical initiation unverified.','development',['KROS101']),('KROS-102','Preclinical GITR-pathway immunomodulator for autoimmune disease.','research',['KROS102']),('KROS-201','Investigational activated T-cell therapy for glioblastoma; IND clearance does not prove treatment dosing.','development',['KROS201']),('KROS-301','Preclinical NF-kB-directed cancer programme.','research',['KROS301']),('KROS-401','Preclinical cyclic-peptide IL4/IL13 receptor pathway programme.','research',['KROS401']),('ENV-205','Preclinical mitochondrial-DNA-directed biologic programme for chemotherapy resistance.','research',['ENV205'])]
prods=[p(n,desc,a,life,aliases=aliases,evidence=[a,b,e]+([c,d] if n=='ENV-105' else [])) for n,desc,life,aliases in specs]
co=company('Kairos Pharma, Ltd.',prods,[a,b,c,d,e],'All seven programmes named in public issuer technology page,pipeline and2026 annual disclosure reviewed and entered. Same ENV105 prostate/lung candidate grouped; no duplicate per indication. Partner standard-of-care drugs excluded. Actual dosing of projected trials,precise licensing territories and future approvals not inferred. Completed discovery of publicly named seven-programme portfolio as of scan.',status='complete')
(out/'batch-0136.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(prods))
